/**
 * Turns stored ids into the hrefs the App Router actually serves.
 *
 * Notifications and search hits are written far from any route, and only carry
 * ULIDs; the pages are addressed by org slug, project slug and issue number.
 * These helpers do the lookups and hand the result to `@/lib/url`, so no
 * service ever concatenates a path by hand. A row that has disappeared
 * degrades to the organization's dashboard rather than to a dead link.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

async function orgSlugFor(orgId: OrgId): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? null;
}

/** `/{org}/projects/{project}/issues/{number}` for one issue. */
export async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  if (orgSlug === null) return "/";

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(orgSlug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(orgSlug);

  return issuePath(orgSlug, project.slug, issue.number);
}

/** A comment has no page of its own; it lives on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) {
    const orgSlug = await orgSlugFor(orgId);
    return orgSlug === null ? "/" : orgPath(orgSlug);
  }
  return issueHref(orgId, comment.issueId);
}

/** `/{org}/projects/{project}` for one project. */
export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  if (orgSlug === null) return "/";

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project) return orgPath(orgSlug);

  return projectPath(orgSlug, project.slug);
}

/** `/{org}/settings/{section}`, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  return orgSlug === null ? "/" : settingsPath(orgSlug, section);
}

