new='''/**
 * Every write refused because the plan has no room for it reports here before
 * it throws: the breach event goes out and the workspace owner is alerted,
 * whoever attempted the write. Only refusals call this — a recount that merely
 * observes usage never does.
 */
export async function reportLimitRefusal(
  orgId: OrgId,
  refusal: { resource: LimitedResource; limit: number; used: number },
  actorId: UserId | null = null,
): Promise<void> {
  await emit("billing.limit_exceeded", {
    ...envelope(orgId, actorId),
    resource: refusal.resource,
    limit: refusal.limit,
    used: refusal.used,
  });
  await notifyPlanLimitReached(orgId, refusal);
}

