import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("#t/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("#t/server/_support/doubles/misc")).rateLimitModule);

import { hashToken } from "@/lib/hash";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import * as invitationService from "@/server/services/invitation-service";
import * as webhookService from "@/server/services/webhook-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as usageService from "@/server/services/usage-service";
import * as searchService from "@/server/services/search-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { buildDigest } from "@/server/services/digest-service";
import {
  listNotifications, markAllRead, markRead, notify, updatePreference,
} from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "#t/server/_support/fixtures";
import type { Tenant } from "#t/server/_support/fixtures";
import type { Actor } from "@/types/member";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  t = await createTenant("acme", "growth");
});
afterAll(() => cleanup());

async function inbox(actor: Actor, kind?: string[], limit = 100, cursor: string | null = null, unreadOnly = false) {
  return listNotifications(actor, { orgId: actor.orgId, recipientId: actor.userId, unreadOnly, kind: kind as never, limit, cursor });
}

describe("personal inboxes", () => {
  it("refuses another member's inbox, mark-read and preferences, for every role", async () => {
    const [n] = await notify(t.org.id, "comment_created", [t.userIds.admin], { title: "x", body: "x", href: "/x", actorId: null });
    for (const role of ["owner", "member", "viewer"] as const) {
      await expect(listNotifications(t.actors[role], { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, limit: 25, cursor: null })).rejects.toThrow(/Permission denied/);
      await expect(markRead(t.actors[role], { orgId: t.org.id, notificationId: n!.id })).rejects.toThrow(/Permission denied/);
      await expect(updatePreference(t.actors[role], { orgId: t.org.id, userId: t.userIds.admin, kind: "issue_assigned", inApp: false, email: false, digestOnly: false })).rejects.toThrow(/Permission denied/);
    }
    const still = await notificationRepo.findNotificationById(t.org.id, n!.id);
    expect(still?.readAt).toBeNull();
    const marked = await markRead(t.actors.admin, { orgId: t.org.id, notificationId: n!.id });
    expect(marked.readAt).not.toBeNull();
    await expect(updatePreference(t.actors.viewer, { orgId: t.org.id, userId: t.userIds.viewer, kind: "issue_assigned", inApp: true, email: false, digestOnly: false })).resolves.toBeTruthy();
  });

  it("mark all read touches only the caller's own rows", async () => {
    const x = await createTenant("markall", "growth");
